  await new Promise((r) => setTimeout(r, 200));

  const mid = await form(page);
  assert.equal(mid.submitDisabled, true);
  assert.equal(mid.game, 'ludo');
  assert.equal(mid.capacity, '4');
  assert.equal(mid.capacityDisabled, false);
  assert.equal(mid.turnSeconds, '60');
  assert.equal(mid.name, '后来的飞行棋');

  // 回车也不能触发第二次提交。
  await page.focus('#name');
  await page.keyboard.press('Enter');
  await new Promise((r) => setTimeout(r, 200));

  release();
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'));

  const f = await form(page);
