  const id = m.text.split('编号：')[1].split('。')[0];
  assert.ok(id);
  assert.ok(m.text.includes('尚未提交'), '应说明当前填写内容尚未提交: ' + m.text);

  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 2);
  const rows = await page.$$eval('#list-area table tbody tr', (trs) => trs.map((tr) =>
    [...tr.querySelectorAll('td')].slice(0, 5).map((td) => td.textContent)));
  assert.deepEqual(rows[1].slice(1, 5), ['等待的五子棋', '五子棋', '2 人', '不限时']);

