  await page.click('#submit');
  await page.waitForFunction(() => {
    const el = document.getElementById('form-msg');
    const t = el.textContent;
    return el.classList.contains('ok') && !t.includes('尚未提交');
  });
  await page.waitForFunction(() => document.querySelectorAll('#list-area table tbody tr').length === 3);
  const rows2 = await page.$$eval('#list-area table tbody tr', (trs) => trs.map((tr) =>
    [...tr.querySelectorAll('td')].slice(0, 5).map((td) => td.textContent)));
  assert.deepEqual(rows2[2].slice(1, 5), ['后来的飞行棋', '飞行棋', '4 人', '60 秒']);
  const f2 = await form(page);
