  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'));
  const f = await form(page);
  assert.equal(f.name, '  空格房间  ');
  assert.equal(f.game, 'gomoku');
  assert.equal(f.capacity, '2');
  assert.equal(f.turnSeconds, '0');
  assert.ok((await msg(page)).text.includes('尚未提交'));
});

