test('等待期间改过又完整恢复到提交时全部值：按未改变处理，复位', async (t) => {
  const { page } = await setupPage(t);
  await page.setRequestInterception(true);
  const release = holdFirstPost(page);
  await page.type('#name', '恢复房间');
  await page.select('#game', 'ludo');
  await page.waitForFunction(() => !document.getElementById('capacity').disabled);
  await page.select('#capacity', '3');
  await page.type('#turnSeconds', '60');
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('submit').disabled);
  await page.$eval('#name', (el) => { el.value = '改过'; });
  await page.select('#game', 'gomoku');
  await page.waitForFunction(() => document.getElementById('capacity').value === '2');
  await page.$eval('#turnSeconds', (el) => { el.value = '100'; });
  // 再全部改回
  await page.$eval('#name', (el) => { el.value = '恢复房间'; });
  await page.select('#game', 'ludo');
  await page.waitForFunction(() => !document.getElementById('capacity').disabled);
  await page.select('#capacity', '3');
  await page.$eval('#turnSeconds', (el) => { el.value = '60'; });
  release();
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'));
  const f = await form(page);
  assert.deepEqual(f, { name: '', game: '', capacity: '', capacityDisabled: true, turnSeconds: '', submitDisabled: false });
});

test('等待期间改成未填完整的配置：成功返回时原样保留，不补齐不清空，提交时仍走现有校验', async (t) => {
  const { page } = await setupPage(t);
  await page.setRequestInterception(true);
  const release = holdFirstPost(page);
  await fillGomoku(page, '完整提交的房间');
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('submit').disabled);
  // 改成未选规则（人数随之禁用）
  await page.select('#game', '');
  await page.$eval('#turnSeconds', (el) => { el.value = ''; });
  release();
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('ok'));
  const f = await form(page);
  assert.deepEqual(f, { name: '完整提交的房间', game: '', capacity: '', capacityDisabled: true, turnSeconds: '', submitDisabled: false });
  // 再次提交：现有校验拦截，且不影响保留内容
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('error'));
  assert.equal((await msg(page)).text, '请选择游戏规则。');
  const f2 = await form(page);
  assert.equal(f2.game, '');
  assert.equal(f2.name, '完整提交的房间');
  assert.equal(f2.submitDisabled, false);
});

test('创建被拒绝：沿用原因提示并保留等待期间最新填写，不回退', async (t) => {
  const { page } = await setupPage(t);
  await page.setRequestInterception(true);
  let release;
  const held = new Promise((r) => { release = r; });
  let first = true;
  page.on('request', (req) => {
    if (first && req.method() === 'POST' && req.url().endsWith('/api/rooms')) {
      first = false;
      held.then(() => req.respond({
        status: 400, contentType: 'application/json; charset=utf-8',
        body: JSON.stringify({ error: '拒绝原因XYZ' }),
      }));
    } else req.continue();
  });
  await fillGomoku(page, '被拒房间');
  await page.click('#submit');
  await page.waitForFunction(() => document.getElementById('submit').disabled);
  await page.$eval('#name', (el) => { el.value = '拒绝后保留的名称'; });
  await page.select('#game', 'ludo');
  await page.waitForFunction(() => !document.getElementById('capacity').disabled);
  await page.select('#capacity', '4');
  await page.$eval('#turnSeconds', (el) => { el.value = '30'; });
  release();
  await page.waitForFunction(() => document.getElementById('form-msg').classList.contains('error'));
  assert.equal((await msg(page)).text, '拒绝原因XYZ');
  const f = await form(page);
  assert.deepEqual(f, {
    name: '拒绝后保留的名称', game: 'ludo', capacity: '4', capacityDisabled: false,
    turnSeconds: '30', submitDisabled: false,
  });
});

